async function loadCatalog(){catalogAbort?.abort();const controller=catalogAbort=new AbortController(),version=++catalogRequest,t=viewStamp();let d;catalogLoading=true;try{d=await api(cityPath(`/organizations?limit=24&q=${encodeURIComponent(S.catalogSearch)}${S.catalogCursor?'&cursor='+encodeURIComponent(S.catalogCursor):''}`),'GET',undefined,{signal:controller.signal});}catch(error){if(version===catalogRequest)catalogLoading=false;if(controller.signal.aborted)return;throw error;}if(version===catalogRequest)catalogLoading=false;if(version!==catalogRequest||!currentView(t)||S.tab!=='organizations'||!$('catalog-results'))return;S.catalogLimit=d.limit||24;S.catalogNext=d.next_cursor||null;d.offset=S.catalogOffset;S.catalog=d.items;S.catalogTotal=d.total;$('catalog-results').innerHTML=`<p class="muted">Найдено ${d.total} · записи ${d.total?d.offset+1:0}–${Math.min(d.total,d.offset+d.items.length)}</p><div class="grid">${d.items.map(o=>`<button class="quest-card" data-org="${esc(o.id)}"><span class="tag">${esc(o.category)}</span><h3 style="margin-top:12px">${esc(o.name)}</h3><p>${esc(o.address||cityName())}</p></button>`).join('')||'<div class="empty">Мест по этому запросу нет.</div>'}</div><div class="form-actions">${d.offset?'<button class="button" data-action="catalog-prev">← Назад</button>':''}${d.offset+d.items.length<d.total?'<button class="button" data-action="catalog-next">Далее →</button>':''}</div>`;}
function serviceContacts(){const c=S.config.contacts||{},links=[];for(const [key,title] of [['termsUrl','Условия использования'],['privacyUrl','Конфиденциальность']]){try{const u=new URL(c[key]);if(u.protocol==='https:')links.push(`<a href="${esc(u.href)}" target="_blank" rel="noopener noreferrer">${title} ↗</a>`);}catch{}}if(typeof c.supportEmail==='string'&&/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(c.supportEmail))links.push(`<a href="mailto:${esc(c.supportEmail)}">Связаться с поддержкой</a>`);return links.length?`<div class="panel"><h2>Информация о сервисе</h2><div class="actions">${links.join('')}</div></div>`:'';}
function renderProfile(){const user=S.user;$('page-view').innerHTML=pageHead(esc(user.name),'Твоя история исследования города.',`<button class="button" data-action="logout">Выйти</button>`)+`<div class="panel feature-shortcut"><div><h2>Маленький друг. Большой город.</h2><p>Знакомься с питомцем, выращивай его и делись мыслями.</p></div><div class="actions"><button class="button primary" data-tab="pet">Мой питомец ↗</button><button class="button" data-tab="plans">Тарифы</button></div></div><div class="panel-row"><div class="panel"><div class="muted">Уровень ${user.level}</div><div class="stat-value">${user.xp} XP</div><div class="progress-track"><div class="progress-fill" style="width:${(user.xp%levelStep())/levelStep()*100}%"></div></div><p class="help">${levelStep()-user.xp%levelStep()} XP до следующего уровня</p></div><div class="panel"><div class="muted">Твои открытия · ${esc(cityName())}</div><div class="stat-value">${S.cellsTotal} ${plural(S.cellsTotal,['участок','участка','участков'])}</div><p class="help">Пройдено квестов: ${S.completedTotal}</p></div></div><div class="panel"><h2>Геолокация и приватность</h2><p class="muted">GPS включается по твоему действию и останавливается при сворачивании приложения или смене города. После возврата включи GPS снова. Координаты не показываются другим без отдельного согласия. Позиция команды видна не дольше минуты после обновления. Устаревшие координаты удаляются фоново через час; при нагрузке или сбое удаление может задержаться. Можно удалить сейчас.</p><div class="actions"><button class="button" data-action="stop-location">Остановить GPS и удалить позицию</button><button class="button danger" data-action="clear-explored">Сбросить открытые участки</button></div></div><div class="panel"><h2>Аккаунт</h2><p>${esc(user.email)} · ${label(user.role)}</p><p class="help">Идентификатор для индивидуального задания: <code>${esc(user.id)}</code></p></div>${serviceContacts()}<div id="security-panel" class="panel"><h2>Безопасность аккаунта</h2><p class="muted">Загрузка настроек…</p></div><h2>Пройденные истории</h2><div class="grid">${S.quests.filter(q=>q.completed).map(questCard).join('')||'<p class="muted">Первая история ещё впереди.</p>'}</div>`;const securityHost=$('security-panel');loadSecurity().catch(error=>{if(securityHost.isConnected)securityHost.innerHTML='<h2>Безопасность аккаунта</h2><p class="error">'+esc(error.message)+'</p>';});}
async function loadSecurity(){
 const t=viewStamp(),version=++securityRequest;if(!t.user)return;const d=await api('/auth/security');if(version!==securityRequest||!currentView(t)||S.tab!=='profile'||!$('security-panel'))return;
 $('security-panel').innerHTML=`<h2>Безопасность аккаунта</h2>${d.requiresMfaSetup?'<div class="notice">Для доступа к управлению подключи двухфакторную защиту.</div>':''}<div class="security-status"><div><strong>Двухфакторная защита</strong><p class="help">${d.mfaEnabled?'Подключена · приложение-аутентификатор':'Пароль + код из приложения-аутентификатора'}</p></div>${d.passwordLoginEnabled===false?'<span class="tag">Защита через провайдера SSO</span>':`<button class="button ${d.mfaEnabled?'':'primary'}" data-action="${d.mfaEnabled?'mfa-disable':'mfa-setup'}">${d.mfaEnabled?'Отключить':'Подключить'}</button>`}</div><h3>Активные сеансы</h3><div class="session-list">${d.sessions.map(session=>`<div class="session-item"><div><strong>${session.current?'Этот сеанс':'Другой сеанс'}</strong><p class="help">Создан ${esc(new Date(session.created_at).toLocaleString('ru-RU'))}<br>Последняя активность: ${esc(new Date(session.last_seen).toLocaleString('ru-RU'))}</p></div>${session.current?'<span class="tag good">Текущий</span>':`<button class="button small danger" data-revoke-session="${esc(session.id)}">Завершить</button>`}</div>`).join('')}</div><button class="button" data-action="revoke-other-sessions">Завершить остальные сеансы</button>`;
}
